//! On-disk format compatibility: golden table directories under `fixtures/`
//! (see "Formato em disco v1.0" in docs/architecture.md). The `plain_v2`,
//! `ctr_v2`, `wal_v1` and `deleted_v3` fixtures were generated by the code
//! that wrote format v0.x (before authenticated encryption); the current code
//! must read them with identical results. `aead_v3` locks the authenticated
//! format. Regenerate only deliberately: `cargo test -p moosedb-tests
//! gen_fixture -- --ignored`.

use std::path::{Path, PathBuf};

use super::helpers::*;
use moosedb_core::time::MICROS_PER_SEC;
use moosedb_core::{RawOptions, Row, Table};

const KEY: u32 = 7;

fn fixtures() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("fixtures")
}

fn opts(encrypted: bool) -> RawOptions<'static> {
    RawOptions { encryption_key_id: encrypted.then_some(KEY), ..Default::default() }
}

fn copy_dir(from: &Path, to: &Path) {
    std::fs::create_dir_all(to).unwrap();
    for e in std::fs::read_dir(from).unwrap() {
        let e = e.unwrap();
        std::fs::copy(e.path(), to.join(e.file_name())).unwrap();
    }
}

/// 30 rows flushed into a chunk, then 5 rows that stay in the WAL.
fn populate(t: &Table) {
    for i in 0..30 {
        t.write(row(i, if i % 2 == 0 { "srv1" } else { "srv2" }, i as f64)).unwrap();
    }
    t.flush().unwrap();
    for i in 100..105 {
        t.write(row(i, "srv1", i as f64)).unwrap();
    }
    t.sync_wal(true).unwrap();
}

fn rows(secs: impl Iterator<Item = i64>) -> Vec<Row> {
    secs.map(|i| row(i, if i >= 100 || i % 2 == 0 { "srv1" } else { "srv2" }, i as f64)).collect()
}

fn expected(case: &str) -> Vec<Row> {
    match case {
        "wal_v1" => rows((0..30).chain(100..105)),
        "deleted_v3" => rows((10..30).chain(100..105)),
        _ => rows((0..30).chain(100..105)),
    }
}

fn generate(case: &str, encrypted: bool) {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let path = tmp.path().join("t");
    let t = create_open(&path, opts(encrypted));
    match case {
        "wal_v1" => {
            for i in (0..30).chain(100..105) {
                t.write(row(i, if i >= 100 || i % 2 == 0 { "srv1" } else { "srv2" }, i as f64)).unwrap();
            }
            t.sync_wal(true).unwrap();
        }
        "deleted_v3" => {
            populate(&t);
            let hi = base_ts() + 10 * MICROS_PER_SEC - 1;
            t.delete_range(None, base_ts() - MICROS_PER_SEC, hi, None, true).unwrap();
            t.flush().unwrap(); // the flush records the tombstone in a v3 MANIFEST
        }
        _ => populate(&t),
    }
    drop(t);
    if case == "wal_v1" {
        downgrade_wal_to_v1(&path);
    }
    let out = fixtures().join(case);
    let _ = std::fs::remove_dir_all(&out);
    copy_dir(&path, &out);
}

/// Rewrites the (plain, ROW_COMMIT-only) v2 segments of `dir` in the v1
/// layout: version 1, payload = row without the kind byte, CRC recomputed.
fn downgrade_wal_to_v1(dir: &Path) {
    for e in std::fs::read_dir(dir).unwrap() {
        let p = e.unwrap().path();
        if !p.to_string_lossy().ends_with(".tfl.wal") {
            continue;
        }
        let d = std::fs::read(&p).unwrap();
        if d.len() <= 8 {
            continue;
        }
        let mut out = d[..8].to_vec();
        out[4..6].copy_from_slice(&1u16.to_le_bytes());
        let mut pos = 8;
        while pos < d.len() {
            let len = u32::from_le_bytes(d[pos + 4..pos + 8].try_into().unwrap()) as usize;
            let payload = &d[pos + 8..pos + 8 + len];
            assert_eq!(payload[0], 3, "only ROW_COMMIT entries expected");
            let body = &payload[1..];
            let len_bytes = (body.len() as u32).to_le_bytes();
            let mut h = crc32fast::Hasher::new();
            h.update(&len_bytes);
            h.update(body);
            out.extend_from_slice(&h.finalize().to_le_bytes());
            out.extend_from_slice(&len_bytes);
            out.extend_from_slice(body);
            pos += 8 + len;
        }
        std::fs::write(&p, out).unwrap();
    }
}

#[test]
#[ignore = "writes fixtures with the current format"]
fn gen_fixture_legacy() {
    generate("plain_v2", false);
    generate("ctr_v2", true);
    generate("wal_v1", false);
    generate("deleted_v3", false);
}

#[test]
#[ignore = "writes fixtures with the current format"]
fn gen_fixture_aead() {
    generate("aead_v3", true);
}

fn open_case(case: &str, encrypted: bool) -> (tempfile::TempDir, Table) {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let path = tmp.path().join("t");
    copy_dir(&fixtures().join(case), &path);
    let t = Table::open(config(&path, opts(encrypted))).unwrap();
    (tmp, t)
}

fn check_case(case: &str, encrypted: bool) -> (tempfile::TempDir, Table) {
    let (tmp, t) = open_case(case, encrypted);
    assert_eq!(sorted(all_rows(&t)), sorted(expected(case)), "{case}");
    assert!(t.check().unwrap().is_empty(), "{case}: CHECK TABLE");
    (tmp, t)
}

fn chunk_versions(t: &Table) -> Vec<u16> {
    t.chunks().unwrap().iter().map(|c| c.header.version).collect()
}

#[test]
fn plain_v2_is_read_unchanged() {
    let (_d, t) = check_case("plain_v2", false);
    assert_eq!(chunk_versions(&t), vec![2]);
}

#[test]
fn wal_v1_is_replayed() {
    check_case("wal_v1", false);
}

#[test]
fn manifest_v3_with_tombstones_is_read() {
    check_case("deleted_v3", false);
}

#[test]
fn unauthenticated_ctr_files_stay_readable_and_compaction_upgrades_them() {
    let (_d, t) = check_case("ctr_v2", true);
    assert_eq!(chunk_versions(&t), vec![2], "legacy CTR chunk");
    assert!(t.chunks().unwrap().iter().all(|c| c.header.is_encrypted()));
    // The bucket holds that single legacy chunk: OPTIMIZE rewrites it anyway.
    assert_eq!(t.compact(i64::MIN, i64::MAX, base_ts()).unwrap().groups, 1);
    assert_eq!(sorted(all_rows(&t)), sorted(expected("ctr_v2")));
    assert!(chunk_versions(&t).iter().all(|&v| v == 3), "{:?}", chunk_versions(&t));
}

#[test]
fn aead_v3_is_read_unchanged() {
    let (_d, t) = check_case("aead_v3", true);
    assert_eq!(chunk_versions(&t), vec![3]);
}

// --- Tampering -------------------------------------------------------------
// The attacker model: bytes are changed on disk and every checksum is
// recomputed, so only the authentication tags can notice.

fn crc(b: &[u8]) -> [u8; 4] {
    crc32fast::hash(b).to_le_bytes()
}

fn fix_chunk_crcs(b: &mut [u8]) {
    let c = crc(&b[..60]);
    b[60..64].copy_from_slice(&c);
    if b[6] & 2 != 0 {
        let c = crc(&b[64..92]);
        b[92..96].copy_from_slice(&c);
    }
    let f = b.len() - 24;
    let c = crc(&b[..f + 16]);
    b[f + 16..f + 20].copy_from_slice(&c);
}

fn chunk_path(dir: &Path) -> PathBuf {
    std::fs::read_dir(dir).unwrap().map(|e| e.unwrap().path()).find(|p| p.extension().is_some_and(|x| x == "tfl")).unwrap()
}

fn wal_path(dir: &Path) -> PathBuf {
    std::fs::read_dir(dir).unwrap().map(|e| e.unwrap().path()).find(|p| p.to_string_lossy().ends_with(".tfl.wal")).unwrap()
}

/// What a client would see: the open error, the scan error, or the rows.
fn outcome(dir: &Path) -> Result<Vec<Row>, moosedb_core::Error> {
    let t = Table::open(config(dir, opts(true)))?;
    let mut s = t.scan(&Default::default(), false)?;
    let mut out = Vec::new();
    while let Some((_, r)) = s.next_row()? {
        out.push(r);
    }
    Ok(out)
}

fn tampered_copy(f: impl FnOnce(&Path)) -> (tempfile::TempDir, PathBuf) {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let path = tmp.path().join("t");
    copy_dir(&fixtures().join("aead_v3"), &path);
    f(&path);
    (tmp, path)
}

#[test]
fn any_bit_flip_in_an_authenticated_chunk_is_never_served() {
    let size = std::fs::metadata(fixtures().join("aead_v3").join(chunk_path(&fixtures().join("aead_v3")).file_name().unwrap())).unwrap().len() as usize;
    let want = sorted(expected("aead_v3"));
    let (mut failed_in_data, mut data_positions) = (0, 0);
    for pos in 0..size {
        let (_d, path) = tampered_copy(|p| {
            let c = chunk_path(p);
            let mut b = std::fs::read(&c).unwrap();
            b[pos] ^= 1 << (pos % 8);
            fix_chunk_crcs(&mut b);
            std::fs::write(&c, b).unwrap();
        });
        let in_data = (96..size - 24).contains(&pos);
        match outcome(&path) {
            Err(moosedb_core::Error::Corrupt(_) | moosedb_core::Error::Crypto(_) | moosedb_core::Error::NotFound(_)) => {
                failed_in_data += usize::from(in_data);
            }
            Err(e) => panic!("byte {pos}: unexpected error {e}"),
            // Damage visible without the key (header, footer) quarantines the
            // chunk as before: rows go missing, but none is ever altered.
            Ok(rows) => assert!(rows.iter().all(|r| want.contains(r)), "byte {pos}: altered data was served"),
        }
        data_positions += usize::from(in_data);
    }
    assert_eq!(failed_in_data, data_positions, "every byte of blocks and index must be authenticated");
}

#[test]
fn blocks_cannot_be_swapped_between_chunks() {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let make = |name: &str| {
        let p = tmp.path().join(name);
        let t = create_open(&p, opts(true));
        for i in 0..30 {
            t.write(row(i, "srv1", i as f64)).unwrap();
        }
        t.flush().unwrap();
        drop(t);
        p
    };
    let (a, b) = (make("a"), make("b"));
    let (mut ca, cb) = (std::fs::read(chunk_path(&a)).unwrap(), std::fs::read(chunk_path(&b)).unwrap());
    assert_eq!(ca.len(), cb.len());
    // Same logical content, so same layout: move the first blocks of B into A.
    ca[96..160].copy_from_slice(&cb[96..160]);
    assert_ne!(ca, std::fs::read(chunk_path(&a)).unwrap());
    fix_chunk_crcs(&mut ca);
    std::fs::write(chunk_path(&a), ca).unwrap();
    assert!(matches!(outcome(&a), Err(moosedb_core::Error::Corrupt(_))));
    assert_eq!(outcome(&b).unwrap().len(), 30);
}

#[test]
fn any_bit_flip_in_an_authenticated_wal_entry_is_refused() {
    let first = |p: &Path| {
        let w = std::fs::read(wal_path(p)).unwrap();
        let len = u32::from_le_bytes(w[40 + 4..40 + 8].try_into().unwrap()) as usize;
        (w, len)
    };
    let (_, len) = first(&fixtures().join("aead_v3"));
    for pos in 0..len {
        let (_d, path) = tampered_copy(|p| {
            let (mut w, len) = first(p);
            w[48 + pos] ^= 1 << (pos % 8);
            let c = crc(&w[44..48 + len]);
            w[40..44].copy_from_slice(&c);
            std::fs::write(wal_path(p), w).unwrap();
        });
        assert!(matches!(outcome(&path), Err(moosedb_core::Error::Crypto(_))), "WAL byte {pos} was accepted");
    }
}

#[test]
fn a_wal_segment_renamed_to_another_number_is_refused() {
    let (_d, path) = tampered_copy(|p| {
        let w = wal_path(p);
        std::fs::rename(&w, w.with_file_name("wal_000009.tfl.wal")).unwrap();
        // The MANIFEST asks for segments from 2 on: 9 is replayed in its place.
    });
    assert!(outcome(&path).is_err());
}

#[test]
#[ignore = "measures; run with --release -- --ignored --nocapture"]
fn cost_of_authentication() {
    use std::time::Instant;
    crate::encryption_tests::install();
    let n = 600_000i64;
    for (label, encrypted) in [("plain", false), ("encrypted", true)] {
        let tmp = tempfile::tempdir().unwrap();
        let t = create_open(&tmp.path().join("t"), opts(encrypted));
        let t0 = Instant::now();
        for i in 0..n {
            t.write(row(i % 80_000, &format!("srv{}", i % 50), i as f64)).unwrap();
        }
        t.sync_wal(true).unwrap();
        let wal = t0.elapsed();
        t.flush().unwrap();
        let flush = t0.elapsed() - wal;
        let bytes: u64 = t.chunks().unwrap().iter().map(|c| c.file_size).sum();
        let t1 = Instant::now();
        let rows = all_rows(&t).len();
        let scan = t1.elapsed();
        let (n, mb) = (n as f64, bytes as f64 / 1e6);
        println!(
            "{label:9} {rows} rows ({mb:.1} MB of chunk): WAL {:.0} rows/s, flush {:.2} M rows/s, cold scan {:.2} M rows/s",
            n / wal.as_secs_f64(),
            n / flush.as_secs_f64() / 1e6,
            n / scan.as_secs_f64() / 1e6
        );
    }
}

#[test]
fn a_plaintext_wal_segment_in_an_encrypted_table_is_refused() {
    crate::encryption_tests::install();
    let tmp = tempfile::tempdir().unwrap();
    let make = |name: &str, encrypted: bool| {
        let p = tmp.path().join(name);
        let t = create_open(&p, opts(encrypted));
        for i in 0..5 {
            t.write(row(i, "srv1", i as f64)).unwrap();
        }
        t.sync_wal(true).unwrap();
        drop(t); // rows stay only in the WAL
        p
    };
    let (enc, plain) = (make("enc", true), make("plain", false));
    let enc_wal = std::fs::read(wal_path(&enc)).unwrap();
    std::fs::write(wal_path(&enc), std::fs::read(wal_path(&plain)).unwrap()).unwrap();
    assert!(matches!(outcome(&enc), Err(moosedb_core::Error::InvalidArg(_) | moosedb_core::Error::Corrupt(_))));
    // The reverse is refused the same way as for chunks.
    std::fs::write(wal_path(&plain), enc_wal).unwrap();
    assert!(Table::open(config(&plain, opts(false))).is_err());
}
